INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60470, 0, 0, 'WHO?! Evermoon asking if I am weak?! Evermoon want to kill me huh?! Who are you, messenger, scout?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66668'),
(60470, 1, 0, 'You think you can probe me for weakness?!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66669'),
(61147, 0, 0, 'Do you feel the sense of relief in the air now? You should feel proud.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66599'),
(61143, 0, 0, 'Hey! We should meditate together some time. We are cut from the same cloth, you and I.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66600'),
(91288, 0, 0, 'May my family staff serve you well $N.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67033'),
(70022, 0, 0, 'I will go find my spear right this momen- <argh> -nt!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66175'),
(70020, 0, 0, 'You\'re not going anywhere until fully healed Norvok, I am more than certain our friend will keep an eye out for your spear.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66176'),
(60409, 0, 0, 'Don\'t you just love, when the experiment simply shows up on your doorstep?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66189');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9060470, 'Who are you?! Begone, this is my home, you do not belong here!', 'Who are you?! Begone, this is my home, you do not belong here!', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9060470, 9060470);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9060470, 0, 0, 'Daela Evermoon was asking if you were okay.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 9060470, 0, 0, 0, 47, 0, 40197, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9061147, 'An outsider, why hello.\n\nThis glade was once revered by many druids before the Third War, it is here we communed with nature and the spirits of the forest itself. As of late, the orcs have disturbed this place of sanctuary, the burden now lays on our shoulders to help restore this place.\n\nNo doubt you have seen sentinels about, they have also added to the growing headache that is Forest Song as of late.', 'An outsider, why hello.\n\nThis glade was once revered by many druids before the Third War, it is here we communed with nature and the spirits of the forest itself. As of late, the orcs have disturbed this place of sanctuary, the burden now lays on our shoulders to help restore this place.\n\nNo doubt you have seen sentinels about, they have also added to the growing headache that is Forest Song as of late.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9061147, 9061147);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9061147, 0, 0, 'What seems to be the matter between the druids and the sentinels here in Forest Song?', 0, 1, 1, 9030082, 0, 0, 0, NULL, 0, 0);
