INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 9061147, 1, 0, 0, 47, 0, 40807, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030082, 'It\'s a matter of strategy and value of life. That\'s what this all comes down to. Starwind has rallied those who she commands, made their blood boil with speeches about glory and defending the homeland. Noble, but we are not some troll berserkers! We are Kaldorei, noble, strong, intelligent. It is with the greatest of pain in my chest I see apprentices and young sentinel sisters, some barely past their first century, racing off to skirmish with orcs and goblins in the felled trees of our homeland.', 'It\'s a matter of strategy and value of life. That\'s what this all comes down to. Starwind has rallied those who she commands, made their blood boil with speeches about glory and defending the homeland. Noble, but we are not some troll berserkers! We are Kaldorei, noble, strong, intelligent. It is with the greatest of pain in my chest I see apprentices and young sentinel sisters, some barely past their first century, racing off to skirmish with orcs and goblins in the felled trees of our homeland.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030082, 9030082);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030082, 0, 0, 'Then why not help them? Commander Starwind wishes the druids to fight with the sentinels!', 0, 1, 1, 9030083, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030083, 'Of course we could help them. We could charge into the fray with the others, into a maelstrom of steel and claws, blood and rage. We could grab the horde where they are strongest, and use our brute strength to expel them. But to think I would give the call, to be responsible for loss of life when it is so preventable? Then you are as foolish as her.', 'Of course we could help them. We could charge into the fray with the others, into a maelstrom of steel and claws, blood and rage. We could grab the horde where they are strongest, and use our brute strength to expel them. But to think I would give the call, to be responsible for loss of life when it is so preventable? Then you are as foolish as her.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030083, 9030083);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030083, 0, 0, 'So you will just stand here and do nothing?', 0, 1, 1, 9030084, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030084, 'No! There are weaknesses we can exploit, key parts of the horde war machine we can destroy, leaving them helpless. We can win this war with minimal danger. As I mentioned, the hawk does not stand in front of the fox and fight on its terms...', 'No! There are weaknesses we can exploit, key parts of the horde war machine we can destroy, leaving them helpless. We can win this war with minimal danger. As I mentioned, the hawk does not stand in front of the fox and fight on its terms...', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030084, 9030084);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030084, 0, 0, 'The sentinels will merely be a distraction then. Their loss of blood will be a way to strike at the backlines?', 0, 1, 1, 9030085, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030085, 'Precisely. It may seem cold and calculated to think of it like that, but I am not the one who sent young sisters into a pointless battle. My conscience is clear; this will be the quickest and most effective way of winning. Trust me, even if that brash commander does not!', 'Precisely. It may seem cold and calculated to think of it like that, but I am not the one who sent young sisters into a pointless battle. My conscience is clear; this will be the quickest and most effective way of winning. Trust me, even if that brash commander does not!', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030085, 9030085);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030085, 0, 0, 'I must think about this.', 0, 1, 1, 9030086, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030086, 'Of course, speak to Commander Starwind if you haven\'t already. But know this - every hour that goes by, another chosen of Elune will be laying clover-clad.', 'Of course, speak to Commander Starwind if you haven\'t already. But know this - every hour that goes by, another chosen of Elune will be laying clover-clad.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030086, 9030086);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9061143, 'Why hello there outsider, and welcome to Forest Song.\n\nThis place was once a tranquil glade of our past, though now it is simply ruins. We are doing our part here to maintain the area, and to combat the Warsong Clan from gaining more of a foothold within our sacred forests. They have a lot of tenacity, and vigor, especially for Greenskins, and must be put to an end.\n\nPerhaps you can assist us, for we have many troubles, both inside, and outside.', 'Why hello there outsider, and welcome to Forest Song.\n\nThis place was once a tranquil glade of our past, though now it is simply ruins. We are doing our part here to maintain the area, and to combat the Warsong Clan from gaining more of a foothold within our sacred forests. They have a lot of tenacity, and vigor, especially for Greenskins, and must be put to an end.\n\nPerhaps you can assist us, for we have many troubles, both inside, and outside.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9061143, 9061143);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9061143, 0, 0, 'What seems to be the matter between the sentinels and the druids here in Forest Song?', 0, 1, 1, 9030087, 0, 0, 0, NULL, 0, 0);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 9061143, 0, 0, 0, 47, 0, 40801, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9061143, 1, 0, 'What seems to be the matter between the sentinels and the druids here in Forest Song?', 0, 1, 1, 9030087, 0, 0, 0, NULL, 0, 0);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 9061143, 1, 0, 0, 47, 0, 40807, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030087, 'The moment our scouts reported the incursions into our land, I rallied those stationed nearby. Indecision has led to the Horde developing outposts and building lumber mills!$B$BNo more, we say. Most of us have already gone to fight, but Ironglade speaks about hatching some master plan, of deception and whatever. Well, while he talks from the comfort of his chair, we are busy fighting. And the coward refuses to help, he wishes us to retreat and regroup!', 'The moment our scouts reported the incursions into our land, I rallied those stationed nearby. Indecision has led to the Horde developing outposts and building lumber mills!$B$BNo more, we say. Most of us have already gone to fight, but Ironglade speaks about hatching some master plan, of deception and whatever. Well, while he talks from the comfort of his chair, we are busy fighting. And the coward refuses to help, he wishes us to retreat and regroup!', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030087, 9030087);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030087, 0, 0, 'Then why not retreat? Brolthan Ironglade wishes to aid once everyone is back to Forest Song safely!', 0, 1, 1, 9030088, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030088, '$c, you don\'t know much about our way of fighting, do you? We can blend into the shadows under the canopy of the trees, strike when we need to strike.$B$BThere is strength in this: a retreating sister will be aided by unseen arrows and knives. If we all retreat, the blood lost so far will be for nought, and many of us will be killed and captured in the process. Absolutely not.', '$c, you don\'t know much about our way of fighting, do you? We can blend into the shadows under the canopy of the trees, strike when we need to strike.$B$BThere is strength in this: a retreating sister will be aided by unseen arrows and knives. If we all retreat, the blood lost so far will be for nought, and many of us will be killed and captured in the process. Absolutely not.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030088, 9030088);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030088, 0, 0, 'So you will just continue fighting without a plan, without regrouping?', 0, 1, 1, 9030089, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030089, 'We haven\'t got a choice. I will not show the Horde our backs, or have to explain away the cowardice of retreat, nor will I allow them a chance to capture us as we flee. Lend me your strength, if he will not. Let us break the back of the Horde and show them what it means to trespass into Kaldorei land.', 'We haven\'t got a choice. I will not show the Horde our backs, or have to explain away the cowardice of retreat, nor will I allow them a chance to capture us as we flee. Lend me your strength, if he will not. Let us break the back of the Horde and show them what it means to trespass into Kaldorei land.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030089, 9030089);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030089, 0, 0, 'The druids will be merely bystanders then, while the sentinels sacrifice themselves for glory?', 0, 1, 1, 9030090, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030090, 'Glory is a consequence, we sacrifice for our homeland. And I would much rather make those greenskins die for our homeland than us. Are you in agreement, or do you wish to tarry and delay like the others, while we are actually struggling?', 'Glory is a consequence, we sacrifice for our homeland. And I would much rather make those greenskins die for our homeland than us. Are you in agreement, or do you wish to tarry and delay like the others, while we are actually struggling?', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030090, 9030090);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030090, 0, 0, 'I must think about this.', 0, 1, 1, 9030091, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030091, 'Feel free, but hurry. Talk to Brolthan IronGlade. Come back when you are ready to fight, with or without him.', 'Feel free, but hurry. Talk to Brolthan IronGlade. Come back when you are ready to fight, with or without him.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030091, 9030091);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (6944, 50, 0, 'The young Moonfeather daughter in Forest Song requires your advice. She is struggling in her hippogryph handling training.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 6944, 50, 0, 0, 47, 0, 40799, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (4302, 50, 0, 'The young Moonfeather daughter in Forest Song requires your advice. She is struggling in her hippogryph handling training.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 4302, 50, 0, 0, 47, 0, 40799, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030077, 'Alleana? Ah, I see. She should have visited in person! Of course I will help.$B$B Tell her that it is all about apperance and mannerisms: Speaking to the fledglings not as a parent, not as a master, but as a friend and an equal. They will respect this approach, and only by earning their respect can she hope to bridge the gap between them.$B$BRemember that they are still wild creatures. Their strength and service they lend to us by their own will, not because we tame them or demand it of them.$B$BPlease return to Allie with this advice, and if you could also tell her... I often still press my lips to her letters at night. She really should come visit me for private tutelage someday.', 'Alleana? Ah, I see. She should have visited in person! Of course I will help.$B$B Tell her that it is all about apperance and mannerisms: Speaking to the fledglings not as a parent, not as a master, but as a friend and an equal. They will respect this approach, and only by earning their respect can she hope to bridge the gap between them.$B$BRemember that they are still wild creatures. Their strength and service they lend to us by their own will, not because we tame them or demand it of them.$B$BPlease return to Allie with this advice, and if you could also tell her... I often still press my lips to her letters at night. She really should come visit me for private tutelage someday.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030077, 9030077);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030078, 'Yes, Alleana did write to me with her concerns a few months back. Those Moonfeathers are blessed in that they have a natural talent for communion with Elune’s favored creatures, who look upon them with respect. $B$BHmm... If they do not acknowledge her or her words, perhaps she has not yet gained the respect of the forest. The fledglings will know if she is one of their chosen by instinct alone. It has been too long since I visited the forests of our birth, but I am certain there must be a forest king or patriarch who would judge her as worthy.$B$BPerhaps she should seek out one of these creatures and earn their favor.', 'Yes, Alleana did write to me with her concerns a few months back. Those Moonfeathers are blessed in that they have a natural talent for communion with Elune’s favored creatures, who look upon them with respect. $B$BHmm... If they do not acknowledge her or her words, perhaps she has not yet gained the respect of the forest. The fledglings will know if she is one of their chosen by instinct alone. It has been too long since I visited the forests of our birth, but I am certain there must be a forest king or patriarch who would judge her as worthy.$B$BPerhaps she should seek out one of these creatures and earn their favor.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030078, 9030078);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030079, 'Oh my word, how awful!$B$BAlleana is a Moonfeather, yes? I have every confidence she will find the method that works best for her. Every master handles the hippogryphs differently, as it is an intensely personal practice.$B$BThat said, I have heard the eastern reaches of our sacred forests are being ravaged much like the north. My condolences go out to her, and may Elune grant her strength. Perhaps taking a break to relax her mind would help.$B$BOne cannot hope to calm a wild beast while also being of an uncalm mind, after all.', 'Oh my word, how awful!$B$BAlleana is a Moonfeather, yes? I have every confidence she will find the method that works best for her. Every master handles the hippogryphs differently, as it is an intensely personal practice.$B$BThat said, I have heard the eastern reaches of our sacred forests are being ravaged much like the north. My condolences go out to her, and may Elune grant her strength. Perhaps taking a break to relax her mind would help.$B$BOne cannot hope to calm a wild beast while also being of an uncalm mind, after all.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030079, 9030079);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030080, '<He looks up from replenishing the food for his charges and wipes the sweat from his brow with mucky, worn hands.>$B$BI am extremely busy right now performing my duties, $c. If Alleana wishes to follow in her siblings\'\' footsteps, she had best be prepared to put in the hours, days, years of blood, sweat, and tears to earn such an austere position.$B$BYou will excuse me.', '<He looks up from replenishing the food for his charges and wipes the sweat from his brow with mucky, worn hands.>$B$BI am extremely busy right now performing my duties, $c. If Alleana wishes to follow in her siblings\'\' footsteps, she had best be prepared to put in the hours, days, years of blood, sweat, and tears to earn such an austere position.$B$BYou will excuse me.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030080, 9030080);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030081, 'Sharptalon tenses visibly as you approach, but relaxes at the mention of the Moonfeather name. Eventually, his wings stop beating, he nestles to the ground below, and bows his head, letting out a deferential trill.', 'Sharptalon tenses visibly as you approach, but relaxes at the mention of the Moonfeather name. Eventually, his wings stop beating, he nestles to the ground below, and bows his head, letting out a deferential trill.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030081, 9030081);
